def verify():
    assert abs(1e-14 * math.exp(0.6 / 0.026) * 1e3 - 0.105) < 0.003
    assert abs((12 - 5.1) / 690 * 1e3 - 10) < 0.01 and abs((12 - 5.1) / 690 * 1e3 - 5.1 - 4.9) < 0.01
    assert abs(100 / 101 - 0.990) < 0.001 and abs(12 * 10 / 50 - 0.7 - 1.7) < 1e-9
    assert abs(1e-3 / 0.025 - 0.04) < 1e-12 and abs(100 / 0.04 - 2500) < 1e-9 and abs(-0.04 * 5000 + 200) < 1e-9
    assert 0.5 * 2 * 2 ** 2 == 4 and abs(2 * 1e-3 / 0.2 - 0.01) < 1e-12 and abs(1 / (0.02 * 1e-3) - 50000) < 1e-6
    assert abs(20 * math.log10(1000 / 0.1) - 80) < 1e-9
    assert abs(1 / (2 * math.pi * 1600 * 10e-6) - 9.95) < 0.01 and abs(1 / (2 * math.pi * 1e4 * 1e-8) - 1591.5) < 0.1
    assert abs(1000 / 11 - 90.9) < 0.01 and abs(math.pi / 4 * 100 - 78.54) < 0.01
    assert abs(1 / (2 * math.pi * 1e3 * 1e-6) - 159.15) < 0.01


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
